package com.yeyamo_mobile.api.culture_service.interfaces.rest;import static com.yeyamo_mobile.api.culture_service.application.ChallengeDtos.*;import com.yeyamo_mobile.api.culture_service.application.CultureChallengeService;import java.security.Principal;import java.util.*;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/culture")public class CultureChallengeController{private final CultureChallengeService service;public CultureChallengeController(CultureChallengeService s){service=s;}@GetMapping("/challenges")public Page<ChallengeResponse> list(@PageableDefault(size=20,sort="startsAt",direction=Sort.Direction.DESC)Pageable p){return service.list(p);}@GetMapping("/challenges/{id}")public ChallengeResponse get(@PathVariable UUID id){return service.get(id);}@PostMapping("/challenges/{id}/join")public ParticipationResponse join(@PathVariable UUID id,Principal p){return service.join(id,p.getName());}@PostMapping("/challenges/{id}/submissions")@ResponseStatus(HttpStatus.CREATED)public SubmissionResponse submit(@PathVariable UUID id,@RequestBody SubmissionRequest r,Principal p){return service.submit(id,r,p.getName());}@GetMapping("/challenges/{id}/submissions")public Page<SubmissionResponse> submissions(@PathVariable UUID id,@PageableDefault(size=20)Pageable p){return service.accepted(id,p);}@GetMapping("/challenges/me")public List<ParticipationResponse> mine(Principal p){return service.mine(p.getName());}@DeleteMapping("/challenge-submissions/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void withdraw(@PathVariable UUID id,Principal p){service.withdraw(id,p.getName());}}
